def compute(vars):
    payouts = [
        vars["v1"],
        vars["v2"],
        vars["v3"],
        vars["v4"],
        vars["v5"],
    ]
    total_payout = sum(payouts)
    average_payout = total_payout / len(payouts)

    return {
        "value": average_payout,
        "trace": {
            "payouts": payouts,
            "total_payout": total_payout,
            "count": len(payouts),
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "$",
            },
        },
    }
